class ConfPeriodosTiposPago extends BaseConfPeriodosTiposPago
{

    public static function obtenerFechasPeridosXIdPeriodosTiposPago($idperiodostipospago)
    {
        return Doctrine::getTable('ConfPeriodosTiposPago')->find($idperiodostipospago);
    }

    public static function obtenerListadoFechas($identidad, $idtipopago, $idperiodopago)
    {
        return Doctrine_Query::create()
            ->select('cptp.*, cdp.*')
            ->from('ConfPeriodosTiposPago cptp')
            ->innerJoin('cptp.ConfDesglosePeriodos cdp')
            ->where('cptp.idestructura = ? and cptp.idtipopago = ? and cptp.idperiodopago = ?', array($identidad, $idtipopago, $idperiodopago))
            ->orderBy('cdp.fdesde')
            ->fetchArray();
    }

    public static function obtenerPeriodoExistente($identidad, $idtipopago, $idperiodopago)
    {
        return Doctrine_Query::create()
            ->select('cptp.*')
            ->from('ConfPeriodosTiposPago cptp')
            ->where('cptp.idestructura = ? and cptp.idtipopago = ? and cptp.idperiodopago = ?', array($identidad, $idtipopago, $idperiodopago))
            ->fetchArray();
    }

    public static function obtenerTodosPeriodos()
    {
        return Doctrine_Query::create()
            ->select('cptp.*')
            ->from('ConfPeriodosTiposPago cptp')
            ->fetchArray();
    }

}
